targets:
  home_win: target_home_win
  home_margin: target_home_margin
  total_points: target_total_points

training:
  seed: 20260726
  minimum_training_seasons: 5
  training_seasons_window: 4
  calibration_fit_fraction: 0.60
  final_test_seasons: 1
  logistic_regression:
    C: 0.5
    max_iter: 3000
  blend:
    max_challenger_weight: 0.50
  total_model:
    strategy: baseline_residual_blend
    baseline_feature: feature_model_predicted_total
    max_residual_weight: 0.35
    weight_step: 0.05
    max_abs_adjustment: 4.0
    minimum_selection_mae_improvement: 0.10
  xgboost_classifier:
    n_estimators: 250
    max_depth: 3
    learning_rate: 0.035
    subsample: 0.85
    colsample_bytree: 0.80
    reg_lambda: 3.0
    min_child_weight: 5.0
  xgboost_regressor:
    n_estimators: 300
    max_depth: 3
    learning_rate: 0.035
    subsample: 0.85
    colsample_bytree: 0.80
    reg_lambda: 3.0
    min_child_weight: 5.0
  tuning:
    enabled: true
    trials_per_model: 4
    timeout_seconds_per_model: 180
    validation_seasons: 1
    n_jobs: 1
    search_space:
      n_estimators: [150, 350]
      max_depth: [2, 4]
      learning_rate: [0.02, 0.08]
      subsample: [0.75, 1.0]
      colsample_bytree: [0.70, 1.0]
      min_child_weight: [2.0, 10.0]
      reg_lambda: [1.0, 8.0]
      reg_alpha: [0.0001, 0.5]
  explanations:
    enabled: true
    max_rows: 128

schema_version: fixture
features: {alpha: {type: float}}
training: {note: "literal ! value"}
